"""Load a run's samples with first-pass answers and notice text."""
import json, os, re


def text_of(m):
    c = m.get('content')
    if isinstance(c, list):
        return ''.join(x.get('text', '') if isinstance(x, dict) else str(x) for x in c)
    return c or ''


def fa(text):
    """final_answer field from a model response."""
    for candidate in [text.strip()] + [b.split('\n', 1)[-1].strip() for b in re.findall(r'```(?:json)?\s*([\s\S]*?)```', text)]:
        try:
            d = json.loads(candidate)
        except Exception:
            continue
        if isinstance(d, dict) and 'final_answer' in d:
            return str(d['final_answer'])
    m = re.findall(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', text, re.S)
    if m:
        try:
            return str(json.loads('"' + m[-1] + '"'))
        except Exception:
            return m[-1]
    return ''


def load_run(tree, task='LawBench'):
    base = f'/workspace/runs/{tree}/{task}/conversations'
    out = []
    for i in sorted(int(x) for x in os.listdir(base) if x.isdigit()):
        for f in sorted(os.listdir(f'{base}/{i:04d}')):
            if not f.startswith('sample-') or not f.endswith('.json'):
                continue
            d = json.load(open(f'{base}/{i:04d}/{f}'))
            msgs = d['messages']
            notice = ''
            first = ''
            for j, m in enumerate(msgs):
                t = text_of(m)
                if m.get('role') == 'user' and 'checked against the training memory' in t:
                    notice = t
                if m.get('role') == 'assistant' and not first and not m.get('tool_calls'):
                    first = fa(t)
            d['_notice'] = notice
            d['_first'] = first
            d['_index'] = i
            d['_sample'] = int(f.split('-')[1].split('.')[0])
            out.append(d)
    return out


def shown(d):
    """tool output the model read."""
    return '\n'.join(text_of(m) for m in d['messages']
                     if m.get('role') == 'tool' or m.get('type') == 'tool')

