"""Score a candidate notice rule over all recorded first passes."""
import json, sys, os
sys.path.insert(0, '/tmp/analysis')
import answer_conventions as ac
from load import load_run, shown

TREES = [
    '9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7',
    'bca9cc83e78c40aec26b992045b54b53d51b049b',
    'e2c96b80fe6f6045ce76e249acfdb3eaab900dfd',
    '8b90b9c533d81d047bcfa360458b9b5b1f664fb9',
    '3c5c61e1a2505a79fcd73b63596601425207a4bb',
    '37a3ebb74a30bacfa2ab2379c86fa408af47a2fd',
]


def corpus():
    out = []
    for tree in TREES:
        prof = json.load(open(f'/workspace/runs/{tree}/LawBench/memory.json'))['answer_profile']
        for r in load_run(tree):
            if not r['_first']:
                continue
            out.append({'tree': tree[:7], 'idx': r['_index'], 's': r['_sample'],
                        'first': r['_first'], 'target': r['target'],
                        'ok': r['was_correct'], 'seen': shown(r), 'profile': prof})
    return out


def score(notice_fn, rows, verbose=False):
    fired_wrong = fired_wrong_useful = fired_right = 0
    for r in rows:
        notice = notice_fn(r)
        if not notice:
            continue
        if r['ok']:
            fired_right += 1
        else:
            fired_wrong += 1
            # useful if every quoted memory wording is (part of) the target
            quoted = [q for q in _quotes(notice)]
            if quoted and any(q in r['target'] for q in quoted):
                fired_wrong_useful += 1
            elif verbose:
                print('  NOT-USEFUL', r['tree'], r['idx'], r['s'], repr(r['first']), '->', repr(r['target']))
                print('    ', notice.replace('\n', ' | ')[:400])
    n_wrong = sum(1 for r in rows if not r['ok'])
    n_right = sum(1 for r in rows if r['ok'])
    return dict(wrong=n_wrong, right=n_right, fired_wrong=fired_wrong,
                fired_wrong_useful=fired_wrong_useful, fired_right=fired_right)


def _quotes(notice):
    import re
    return re.findall(r'"([^"]+)"', notice)

