"""Measure a notice rule by the answer a literal follower of its advice would give."""
import sys, re
sys.path.insert(0, '/tmp/analysis')
sys.path.insert(0, '/workspace')
import answer_conventions as ac
from benchmark.data.evaluators import eval_lawbench


def parse_advice(notice):
    """(item, memory_wording_or_None) pairs the notice tells the model to write."""
    out = []
    for line in notice.splitlines():
        m = re.match(r'- Your answer has "([^"]+)";', line)
        if not m:
            continue
        item = m.group(1)
        quoted = re.findall(r'"([^"]+)"', line)[1:]
        out.append((item, quoted[0] if quoted else None))
    return out


def advice_followed(first, notice):
    """The answer a model that applies each notice line literally would write."""
    pairs = parse_advice(notice)
    if not pairs:
        return first
    text = first
    for item, wording in pairs:
        if wording:
            text = text.replace(item, wording)
        else:
            # "the memory never ends an item with X ... writes that charge without it"
            text = text.replace(item, item[:-1])
    return text


def score(fn, rows, verbose=False):
    """For each sample: does the rule fire, and what does the advice yield."""
    stats = dict(fired=0, fired_wrong=0, fired_right=0, fixed=0, broke=0)
    details = []
    for r in rows:
        notice = fn(r)
        if not notice:
            continue
        stats['fired'] += 1
        was = r['ok']
        after = bool(eval_lawbench(advice_followed(r['first'], notice), r['target'])['correct'])
        if was:
            stats['fired_right'] += 1
        else:
            stats['fired_wrong'] += 1
        if not was and after:
            stats['fixed'] += 1
        if was and not after:
            stats['broke'] += 1
        details.append((r, was, after, notice))
    if verbose:
        return stats, details
    return stats

