"""Parameterised candidate: variant matching with a configurable drift, plus the
ending rule asking the variant test of the item it stripped."""
import sys
sys.path.insert(0, '/tmp/analysis')
import answer_conventions as ac


def make_notice(drift=3, ending_variant=True, use_parts=True):
    def shared_ends(item, other, limit):
        start = 0
        while start < len(item) and start < len(other) and item[start] == other[start]:
            start += 1
        if not start:
            return None
        left, right = item[start:], other[start:]
        end = 0
        while end < len(left) and end < len(right) and left[-1 - end] == right[-1 - end]:
            end += 1
        return start, end, left[: len(left) - end], right[: len(right) - end]

    def dropped(one, other):
        if len(one) > len(other):
            one, other = other, one
        rest = iter(other)
        return all(c in rest for c in one)

    def closest(item, known):
        lowered = item.lower()
        best = None
        for key, entry in known.items():
            middles = shared_ends(lowered, key, drift)
            if middles is None:
                continue
            _start, _end, here, there = middles
            if len(here) > drift or len(there) > drift:
                continue
            if not dropped(here, there):
                continue
            score = (len(key), entry[1])
            if best is None or score > best[0]:
                best = (score, entry)
        return best[1] if best else None

    def ending_notice(item, endings, carriers, parts, known):
        last = item[-1:]
        if not last or not item[:-1] or endings[last] or not carriers[last]:
            return ""
        total = sum(endings.values())
        stripped = item[:-1]
        variant = closest(stripped, known) if ending_variant else None
        if stripped in parts or (use_parts and variant is None):
            if stripped not in parts:
                return ""
            return (
                f'- Your answer has "{item}"; the memory never ends an item with "{last}"'
                f" ({endings[last]} of {total} items end with it, though {carriers[last]} of them"
                f" carry it), so the memory writes that charge without it."
            )
        if variant is None:
            return ""
        known_item, count = variant
        return (
            f'- Your answer has "{item}"; the memory never ends an item with "{last}"'
            f" ({endings[last]} of {total} items end with it, though {carriers[last]} of them"
            f" carry it) and writes that charge as {ac._written(known_item, count)}."
        )

    def notice(profile, answer, seen=""):
        if not isinstance(profile, dict) or not profile.get("vocabulary_like"):
            return ""
        inventory = profile.get("items") or {}
        if not inventory:
            return ""
        known = {}
        for item, count in inventory.items():
            known.setdefault(str(item).lower(), (str(item), count))
        answers = ac._answer_counts(profile)
        endings, carriers = ac._ending_statistics(inventory)
        parts = ac.written_parts(answers)
        lines = []
        for item in ac.answer_items(answer):
            if item.lower() in known:
                continue
            variant = closest(item, known)
            if variant is None:
                line = ending_notice(item, endings, carriers, parts, known)
                if not line:
                    continue
            else:
                known_item, count = variant
                compositions = ac._compositions(known_item, answers, seen)
                if compositions:
                    quoted = ", ".join(ac._written(text, tally) for text, tally in compositions)
                    verb = "answer" if len(compositions) == 1 else "answers"
                    line = (
                        f'- Your answer has "{item}"; the memory writes that charge only inside the'
                        f" complete {verb} {quoted}, never on its own."
                    )
                else:
                    line = f'- Your answer has "{item}"; the memory writes it as {ac._written(known_item, count)}.'
            lines.append(line)
            if len(lines) >= ac.MAX_SUGGESTIONS:
                break
        if not lines:
            return ""
        return ac.NOTICE_HEADER + "\n".join(lines) + ac.NOTICE_FOOTER

    return notice

